// =============================================================================
// api/icon.js - Vercel Serverless Function (the dapp icon for wallet approval)
// -----------------------------------------------------------------------------
// Serves the game's app icon. Reached at the path the wallet actually asks for
// via a REWRITE in vercel.json:
//
//     /icon.png   ->   /api/icon
//
// ── WHY THIS EXISTS (the approval-sheet branding defect, 2026-08-06) ─────────
// Mobile Wallet Adapter wallets render the approval sheet from the `identity`
// object in the authorize request - name, uri, and an icon path RELATIVE to the
// uri (MobileWalletAdapterClient.cs:60-86). We were sending "/icon.png" against
// https://defenders-of-the-realm-v2.vercel.app/ and NOTHING SERVED IT:
// vercel.json publishes "Builds/WebGL" as the static root, and that output
// carries only Build/, StreamingAssets/, index.html and validation-key.txt.
// There is no icon there and there is no public/ directory (a project with an
// explicit outputDirectory does not serve one). The icon fetch 404'd, and a
// wallet that cannot load the dapp icon draws its OWN placeholder - which is
// what the owner saw as "SDK branding, not ours".
//
// ── WHY A FUNCTION AND NOT A STATIC FILE ─────────────────────────────────────
// The static root is a Unity WebGL build output. It is gitignored and it is
// wiped and regenerated by every WebGL build, so anything dropped in there is
// lost on the next build and is not reviewable in the repo. A function is
// durable, versioned, and cannot be clobbered by a rebuild - the same reasoning
// that put the Digital Asset Links statement in api/assetlinks.js.
//
// ── KEEP IN SYNC ─────────────────────────────────────────────────────────────
// The identity host and the icon path are declared in
// Assets/_Modules/Wallet/SolanaWalletProvider.cs (DappIdentityUri /
// DappIconUri). If either moves, this endpoint and the vercel.json rewrite move
// with it. WalletIdentityAndPlatformTest asserts the C# half of that contract.
//
// The payload is the game's own 144x144 launcher icon, embedded base64 so the
// function has no filesystem or bundling dependency at cold start. Public art;
// no secrets of any kind belong in this file.
// =============================================================================

// 144x144 PNG - Unity-generated mipmap-xxhdpi app_icon (source: Assets/Branding/AppIcon.png).
const ICON_PNG_BASE64 = '';

const ICON_BYTES = Buffer.from(ICON_PNG_BASE64, 'base64');

module.exports = async (req, res) => {
    // Wallet apps fetch this from their own process/origin, exactly like the
    // assetlinks statement. It is public branding art - keep it wide open.
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, HEAD, OPTIONS');
    if (req.method === 'OPTIONS') { return res.status(204).end(); }

    if (req.method !== 'GET' && req.method !== 'HEAD') {
        return res.status(400).json({ error: 'Method not allowed' });
    }

    res.setHeader('Content-Type', 'image/png');
    res.setHeader('Content-Length', String(ICON_BYTES.length));
    // Long-lived but not immutable: an icon refresh should reach wallets within
    // the day without a cache-busting rename (the icon path is baked into the
    // shipped APK, so it cannot be renamed without a new build).
    res.setHeader('Cache-Control', 'public, max-age=86400, s-maxage=86400, stale-while-revalidate=604800');

    if (req.method === 'HEAD') { return res.status(200).end(); }
    return res.status(200).send(ICON_BYTES);
};
